target.css:
:root {
  --bg-card: #1a1a2e;
  --bg-header: #16213e;
  --bg-section: #0f3460;
  --bg-dial: #e8e0d0;
  --bg-done: #1e3a2f;
  --bg-active: #2d2a14;
  --bg-pending: #1a1f2e;
  --accent-gold: #c9a84c;
  --accent-green: #4caf7d;
  --accent-amber: #f0b429;
  --accent-blue: #5b8dee;
  --text-primary: #f0ece2;
  --text-secondary: #9ba3b8;
  --text-muted: #5c6480;
  --border-subtle: #2a2f4a;
  --hand-color: #2c2c2c;
  --dot-done: #4caf7d;
  --dot-active: #f0b429;
  --dot-pending: #5b8dee;
  --badge-done-bg: #1e3a2f;
  --badge-done-text: #4caf7d;
  --badge-active-bg: #3a2d10;
  --badge-active-text: #f0b429;
  --badge-pending-bg: #1a2540;
  --badge-pending-text: #5b8dee;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.passport {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  width: 480px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.passport-header {
  background: var(--bg-header);
  border-bottom: 1px solid var(--border-subtle);
  padding: 7px 13px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand-mark {
  display: flex;
  align-items: center;
  gap: 7px;
}

.brand-icon {
  font-size: 16px;
  line-height: 1;
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--accent-gold);
}

.brand-sub {
  font-size: 8px;
  color: var(--text-secondary);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.passport-id {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.id-label {
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.15em;
  color: var(--text-muted);
  text-transform: uppercase;
}

.id-value {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-primary);
}

.main-body {
  display: flex;
  gap: 0;
  flex: 1;
}

.watch-face {
  flex-shrink: 0;
  width: 130px;
  background: var(--bg-header);
  border-right: 1px solid var(--border-subtle);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 10px 8px;
  gap: 5px;
  margin: 0;
}

.watch-dial {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  border: 3px solid var(--accent-gold);
  background: var(--bg-dial);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  transform-origin: bottom center;
  background: var(--hand-color);
  border-radius: 2px;
}

.hand.hour {
  width: 3px;
  height: 15px;
  margin-left: -1.5px;
  transform: rotate(-60deg);
}

.hand.minute {
  width: 2px;
  height: 21px;
  margin-left: -1px;
  transform: rotate(120deg);
}

.center-dot {
  position: absolute;
  width: 5px;
  height: 5px;
  background: var(--accent-gold);
  border-radius: 50%;
  z-index: 2;
}

.watch-model {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-primary);
  text-align: center;
  letter-spacing: 0.02em;
}

.watch-movement {
  font-size: 9px;
  color: var(--accent-gold);
  font-weight: 500;
  text-align: center;
  letter-spacing: 0.04em;
}

.watch-specs {
  list-style: none;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: 2px;
}

.watch-specs li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2px 4px;
  border-radius: 4px;
  background: var(--bg-card);
}

.spec-key {
  font-size: 8px;
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.spec-val {
  font-size: 9px;
  color: var(--text-secondary);
  font-weight: 600;
}

.service-log {
  flex: 1;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
}

.log-title {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin-bottom: 7px;
}

.log-entries {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
}

.log-entry {
  display: grid;
  grid-template-columns: 7px 60px 1fr auto;
  align-items: center;
  gap: 7px;
  padding: 5px 7px;
  border-radius: 6px;
  border: 1px solid transparent;
}

.log-entry.done {
  background: var(--bg-done);
}

.log-entry.active {
  background: var(--bg-active);
  border-color: var(--accent-amber);
}

.log-entry.pending {
  background: var(--bg-pending);
}

.entry-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: block;
  flex-shrink: 0;
}

.log-entry.done .entry-dot {
  background: var(--dot-done);
}

.log-entry.active .entry-dot {
  background: var(--dot-active);
}

.log-entry.pending .entry-dot {
  background: var(--dot-pending);
}

.entry-date {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-secondary);
}

.entry-desc {
  font-size: 10px;
  color: var(--text-primary);
  font-weight: 400;
}

.entry-badge {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 2px 5px;
  border-radius: 4px;
}

.log-entry.done .entry-badge {
  background: var(--badge-done-bg);
  color: var(--badge-done-text);
}

.log-entry.active .entry-badge {
  background: var(--badge-active-bg);
  color: var(--badge-active-text);
}

.log-entry.pending .entry-badge {
  background: var(--badge-pending-bg);
  color: var(--badge-pending-text);
}

.passport-footer {
  background: var(--bg-header);
  border-top: 1px solid var(--border-subtle);
  padding: 7px 13px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.technician {
  display: flex;
  flex-direction: column;
}

.tech-label {
  font-size: 8px;
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.tech-name {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-primary);
}

.status-pill {
  font-size: 9px;
  font-weight: 700;
  background: var(--bg-section);
  color: var(--accent-green);
  padding: 4px 10px;
  border-radius: 20px;
  border: 1px solid var(--accent-green);
  letter-spacing: 0.04em;
}

.next-service {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.next-label {
  font-size: 8px;
  color: var(--text-muted);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.next-date {
  font-size: 10px;
  font-weight: 600;
  color: var(--accent-gold);
}

